from pathlib import Path
import re, csv, json, html, subprocess, os

ROOT=Path(__file__).resolve().parents[2]
SRC=ROOT/'Entrevistas'
OUT=ROOT/'Proyecto_Usme_Analisis'
for d in ['01_Validacion','02_Metodologia','03_Data_y_Estadistica','04_Diseno_y_Codigo','05_Presentacion_Final']:
    (OUT/d).mkdir(parents=True,exist_ok=True)

def read(p): return p.read_text(encoding='utf-8-sig',errors='replace')
def norm(s): return re.sub(r'\s+',' ',s).strip()

audio_info={
'Audio1':('00:07:37','07:37','Entrevista; participante identificado en transcripción como Don José'),
'Audio2':('00:00:26','00:26','Fragmento muy breve; Don Álvaro según transcripción'),
'Audio3':('00:08:40','08:40','Entrevista; líder/comerciante Don Álvaro según transcripción'),
'Audio4':('00:08:21','08:21','Entrevista; líder comunitario referido como Don Pérez/Álvaro; posible duplicidad por verificar'),
'Audio5':('00:06:00','06:00','Entrevista; trabajador de fruver Juan Sebastián, según transcripción'),
'Audio6':('No disponible','No disponible','Entrevista; propietaria de local, 36 años en la zona según transcripción'),
'Audio7':('No disponible','No disponible','Entrevista; residente/hogar; transcripción sin cabecera identificadora clara'),
'Audio8':('00:09:28','09:28','Entrevista; residente/comerciante Valentina, según transcripción'),
'Audio9':('00:13:18','13:18','Entrevista; comerciante/residente Isaac, según transcripción'),
'Audio10':('No disponible','No disponible','No parece entrevista sustantiva: transcripción contiene solicitud de firma/permiso; verificar contenido del audio')}

topics={
'separacion_y_cultura':r'\b(separ|cultura|costumbre|concien|educa|capacit|clasific|revolti|mezclad)\w*',
'disposicion_y_recoleccion':r'\b(basur|bolsa|contenedor|caneca|carro|recolec|recog|dispos|botan|bota|horario)\w*',
'impactos_y_salud':r'\b(olor|huele|roedor|rata|mosca|perro|enfermed|infecci|contamin|sucied|plaga)\w*',
'generacion_y_desperdicio':r'\b(sobra|desperd|dañ|dañad|venc|podrid|orgánic|organico|cáscara|cascara|comida|residuo)\w*',
'soluciones_y_participacion':r'\b(soluci|propuest|máquina|maquina|recipiente|separad|compost|abono|aprovech|particip|campaña|campana|incentiv)\w*',
'confianza_y_gobernanza':r'\b(alcald|entidad|gobierno|empresa|servicio|responsab|cobro|pagar|tarifa|confian|junta|líder|lider)\w*'}
neg=re.compile(r'\b(triste|preocup\w*|molest\w*|inconform\w*|frustr\w*|asust\w*|enoj\w*|temor|miedo|angust\w*|decepcion\w*)\b',re.I)
pos=re.compile(r'\b(feliz|content\w*|satisfech\w*|alegr\w*|entusiasm\w*|agradec\w*|encant\w*|orgullos\w*)\b',re.I)

records=[]; inventory=[]
for i in range(1,11):
 stem=f'Audio{i}'; tp=SRC/f'{stem}.txt'; aud=next((p for p in SRC.glob(stem+'.*') if p.suffix.lower() in ['.mp3','.ogg','.mp4','.wav']),None)
 txt=read(tp) if tp.exists() else ''
 words=len(re.findall(r'\b\w+\b',txt,flags=re.UNICODE))
 mins=audio_info[stem][0]
 inventory.append({'id':stem,'audio':aud.name if aud else 'FALTA','transcripcion':tp.name if tp.exists() else 'FALTA','formato':aud.suffix.lower() if aud else '', 'duracion':mins,'palabras_transcripcion':words,'observacion':audio_info[stem][2]})
 if not txt: continue
 # Parse speaker turns; transcript conventions vary across files.
 turns=[]
 lines=txt.splitlines()
 for line in lines:
  line=norm(line)
  if not line: continue
  m=re.match(r'^(Speaker\s*\d+|Entrevistador|Entrevistado|Entrevistada|Don\s+[A-ZÁÉÍÓÚÑ][\wÁÉÍÓÚÑáéíóúñ-]*|Juan Sebastián|Juan Sebastian|Valentina|Isaac|Samuel|WILLIAM HARVEY FONSECA VALERO|Wilinton Javier Ortiz Amador)\s*\([^)]*\)?:\s*(.*)$',line,re.I)
  if not m:
   m=re.match(r'^([^:]{2,65}):\s*(.*)$',line)
  if m:
   sp=norm(m.group(1)); body=norm(m.group(2))
   if body: turns.append((sp,body))
 # fallback: unnamed transcript lines are retained as unassigned, not attributed to interviewee
 if not turns and txt.strip(): turns=[('Speaker desconocido',norm(txt))]
 q=0
 for speaker,body in turns:
  # Preserve short turns as one unit; otherwise split at terminal punctuation, retaining quote content.
  parts=[norm(x) for x in re.split(r'(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÑ¿¡"“(])',body) if norm(x)]
  for part in parts:
   if len(re.findall(r'\b\w+\b',part,flags=re.UNICODE))<3: continue
   q+=1
   is_interviewer=bool(re.search(r'entrevistador|speaker\s*1|wilinton|willington|william|profesor',speaker,re.I))
   labels=[k for k,p in topics.items() if re.search(p,part,re.I)]
   # Sentiment is only an exploratory lexical cue. A score is emitted for respondent speech only.
   n=len(neg.findall(part)); p=len(pos.findall(part)); score=round(max(0,min(5,2.5+(p-n)*0.6)),1) if (p+n)>0 else ''
   if is_interviewer: score=''
   records.append({'unidad_id':f'{stem}-U{q:03d}','archivo':stem,'speaker_transcrito':speaker,'rol_probable':'entrevistador' if is_interviewer else 'participante/no confirmado','texto':part,'temas_regla_exploratoria':';'.join(labels) if labels else 'sin_asignar','valencia_lexica_0a5_exploratoria':score,'limite':'Revisar atribución y codificación humana; no es medición psicológica'})

with (OUT/'01_Validacion'/'inventario_audios_transcripciones.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=inventory[0].keys());w.writeheader();w.writerows(inventory)
with (OUT/'03_Data_y_Estadistica'/'unidades_transcripcion_exploratorias.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=records[0].keys());w.writeheader();w.writerows(records)

respondent=[r for r in records if r['rol_probable']!='entrevistador']
topic_counts={k:sum(k in r['temas_regla_exploratoria'].split(';') for r in respondent) for k in topics}
assigned=sum(bool(r['temas_regla_exploratoria']!='sin_asignar') for r in respondent)
def findquote(pattern,avoid=r''):
 for r in respondent:
  if re.search(pattern,r['texto'],re.I) and (not avoid or not re.search(avoid,r['texto'],re.I)) and 75<len(r['texto'])<330:
   return r
 return next((r for r in respondent if 75<len(r['texto'])<330),{'archivo':'N/D','texto':'Cita pendiente de verificación','speaker_transcrito':'No confirmado'})
quotes=[findquote(p) for p in [r'problema de las basuras es crónico',r'cultura|costumbre|seleccionar',r'cáscara.*misma bolsa|cascara.*misma bolsa',r'falta de cultura',r'olor|huele',r'recogen|recoger',r'compost|abono',r'carísimo|carisimo',r'contenedor|bolsa por fuera',r'no.*separ',r'particip|campaña',r'perro.*bolsa']]

def to_seconds(value):
    if value=='No disponible': return None
    parts=[int(n) for n in value.split(':')]
    return sum(n*(60**(len(parts)-i-1)) for i,n in enumerate(parts))
dur_known=sum(to_seconds(x['duracion']) or 0 for x in inventory)
duration_str=f'{dur_known//3600:02d}:{(dur_known%3600)//60:02d}:{dur_known%60:02d}'
known_duration_count=sum(to_seconds(x['duracion']) is not None for x in inventory)
substantive=[x for x in inventory if int(x['palabras_transcripcion'])>250 and x['id']!='Audio10']

method=f'''# Método y protocolo revisado — Recoevo, trabajo de campo urbano\n\n## Contexto y alcance\nEl proyecto trata del aprovechamiento de residuos orgánicos domésticos y comerciales en la UPZ 57 Gran Yomasa (Usme), Bogotá. El libro de instrumentos establece entrevistas diferenciadas para hogares y locales; el instrumento rural corresponde a una salida posterior y no aplica a este corpus urbano. La hoja de cálculo de COMIDAR/Kennedy existente en el proyecto se excluye como fuente de hallazgos; sólo puede orientar estructura administrativa.\n\n## Unidad de análisis\nLa idea de extraer “frases” es útil si se define como **unidad de significado**: un turno o fragmento que expresa una idea completa, con el contexto mínimo para no alterar el sentido. No conviene cortar mecánicamente cada oración (puede fragmentar una explicación) ni tratar cada unidad como independiente: varias unidades pueden venir de una misma persona y entrevista. Los porcentajes describen este corpus, no la población de Usme.\n\n## Secuencia recomendada\n1. Congelar originales y emparejar audio/transcripción mediante identificador, fecha, rol y metadatos.\n2. Revisar el audio completo junto con la transcripción; corregir texto sin “mejorar” lo dicho. Mantener marcas de inaudible, solapamiento e incertidumbre; registrar responsable, fecha y versión.\n3. Segmentar en unidades de significado conservando `archivo`, hablante, orden y, en el siguiente ciclo, tiempo de audio. Separar voces del entrevistador y participantes.\n4. Codificar en dos pasadas: códigos abiertos inductivos; luego agrupar en categorías y temas del marco (generación, separación, almacenamiento/recolección, impactos, actores, barreras, incentivos, solución). Permitir múltiples códigos y conservar “emergente/otro”.\n5. Aplicar libro de códigos con definición, inclusión/exclusión, ejemplos y decisión para casos ambiguos. Doble codificación de una muestra y resolución documentada; no afirmar confiabilidad intercodificador sin hacerlo.\n6. Sentimiento/valencia es un atributo contextual opcional: separar emoción expresada, objeto de la emoción y polaridad; “estoy feliz” y “la basura está mal” no miden lo mismo. La escala automática 0–5 aquí es sólo una pista léxica exploratoria, no resultado publicable ni diagnóstico. Codificar manualmente una escala ordinal con anclas y opción “no aplicable/ambivalente” antes de presentar caritas.\n7. Analizar por segmento de actor y buscar casos discrepantes. Mostrar conteos de menciones con denominadores claros y citas anonimizadas que preserven contexto.\n8. Triangular sólo con observaciones de campo efectivamente diligenciadas y con documentos del proyecto pertinentes; no convertir guías vacías en observaciones realizadas.\n\n## Privacidad y ética\nEl formato de autorización revisado dice que resultados se presentan agrupados y citas sin nombre. Esta entrega por ello usa IDs de archivo y omite nombres personales en la presentación. Limitar cualquier padrón identificable a acceso interno; verificar que cada grabación tenga permiso firmado y que la finalidad/cita usada quede cubierta. No publicar datos personales inferidos del audio.\n\n## Resultado automático de esta primera pasada\nSe segmentaron **{len(records)}** unidades de texto a partir de transcripciones, de las cuales **{len(respondent)}** quedaron provisionalmente fuera de turnos identificados como entrevistador. **{assigned}** unidades de participante recibieron al menos una etiqueta temática por reglas léxicas; los temas pueden solaparse y requieren auditoría humana. El conteo de unidades no equivale al número de citas válidas ni a “1.000 frases”.\n\nLas duraciones legibles por el sistema suman **{duration_str}** en {sum(bool(re.fullmatch(r'\\d\\d:\\d\\d',x['duracion'])) for x in inventory)} archivos. El total es parcial: Windows no expuso duración para algunos MP4/OGG en los metadatos disponibles. No se pudo hacer comparación acústica/transcripción con reconocimiento automático en este entorno.\n\n## Libro de códigos inicial (provisional)\n| Código | Definición breve | Regla actual |\n|---|---|---|\n'''+''.join(f'| `{k}` | Menciones sobre {k.replace("_"," ")} | Coincidencia de palabras clave; multietiqueta |\n' for k in topics)+'''\nLas reglas de coincidencia sirven para orientar revisión, no para cerrar el análisis temático. Revisar negaciones, ironía, modismos y el contexto de la pregunta.\n\n## Qué falta antes de una publicación como resultado definitivo\nVerificar continuidad/duplicidad entre Audio2–4; escuchar y validar las 10 grabaciones; completar duraciones exactas; asignar código anónimo único por persona; recuperar permisos firmados y fichas demográficas sólo si están autorizadas; cotejar consentimiento y transcripción; completar codificación humana y casos negativos. No se aplican inferencia estadística poblacional, análisis predictivo ni redes neuronales a una muestra pequeña, exploratoria y no probabilística.\n'''
method=method.replace('en 0 archivos',f'en {known_duration_count} archivos')
method=method.replace('La escala automática 0–5 aquí es sólo una pista léxica exploratoria, no resultado publicable ni diagnóstico.','La puntuación léxica 0–5 sólo se asigna si hay términos emocionales explícitos; los demás casos quedan en blanco. En esta pasada no se detectaron expresiones que cumplan esa regla, lo cual no prueba ausencia de emoción. No es resultado publicable ni diagnóstico.')
method=method.replace('4. Codificar en dos pasadas: códigos abiertos inductivos; luego agrupar en categorías y temas del marco (generación, separación, almacenamiento/recolección, impactos, actores, barreras, incentivos, solución). Permitir múltiples códigos y conservar “emergente/otro”.','4. Aplicar análisis de marco (Framework Method) con libro de códigos: es adecuado para este estudio aplicado porque permite comparar sistemáticamente hogares y comercios sin perder el contexto de cada caso. Codificar primero de forma abierta y luego organizar en categorías del proyecto (generación, separación, almacenamiento/recolección, impactos, actores, barreras, incentivos, solución). Permitir varios códigos y conservar “emergente/otro”.')
method+='''

## Fundamentación metodológica
Se elige el **Framework Method / análisis de marco** para una pregunta aplicada que requiere comparar grupos de actores mediante una matriz común de casos y categorías, conservar los extractos de respaldo e interpretar patrones dentro de cada entrevista. El método contempla familiarización, desarrollo del marco analítico, indexación/codificación, organización matricial e interpretación; el marco puede combinar categorías de la pregunta de investigación con códigos emergentes. [Gale et al. (2013), artículo metodológico](https://pmc.ncbi.nlm.nih.gov/articles/PMC3848812/).

Esta elección evita llamar indistintamente “análisis temático” a enfoques con supuestos distintos. Braun y Clarke distinguen enfoques de fiabilidad de codificación, de libro de códigos y reflexivos; las reglas de codificación y comparación propuestas aquí corresponden a un enfoque estructurado de marco/libro de códigos, no a análisis temático reflexivo. [Braun & Clarke (2021), comparación de enfoques](https://doi.org/10.1002/capr.12360).

Para informar la ficha del estudio se toma COREQ como lista de transparencia para entrevistas y grupos focales: equipo investigador, diseño, selección, contexto, guía, grabación, duración, análisis y presentación de citas. Se usa como guía de reporte, no como escala de calidad ni como sustituto de juicio metodológico. [Tong, Sainsbury & Craig (2007), COREQ](https://doi.org/10.1093/intqhc/mzm042).
'''
(OUT/'02_Metodologia'/'Protocolo_y_metodologia.md').write_text(method,encoding='utf-8')

with (OUT/'03_Data_y_Estadistica'/'frecuencias_temas_exploratorias.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f);w.writerow(['tema','unidades_participante_con_match','denominador_unidades_participante','nota']);[w.writerow([k,v,len(respondent),'Conteo de regla léxica; temas solapables; no prevalencia']) for k,v in topic_counts.items()]

qa=f'''# Reporte QA preliminar\n\n## Lo entregado\n- Inventario de {len(inventory)} pares esperados; archivos efectivamente encontrados: {sum(x['audio']!='FALTA' for x in inventory)} audios y {sum(x['transcripcion']!='FALTA' for x in inventory)} transcripciones.\n- {len(substantive)} transcripciones superan 250 palabras; Audio10 se marca como permiso/fragmento, no entrevista sustantiva.\n- Matriz automatizada: {len(records)} unidades de texto; {len(respondent)} unidades provisionalmente atribuibles a participante/no confirmado.\n- Duración verificable parcialmente: {duration_str} en grabaciones reconocidas por metadatos.\n\n## Hallazgos de integridad\n1. Audio2 (26 s) es mucho más corto que las demás y debe tratarse como fragmento. Audio2–4 comparten referencias a Don Álvaro/Don Pérez; no se confirma si son una entrevista partida, dos entrevistas o una identificación inconsistente.\n2. Audio10.txt contiene texto sobre firma/permiso de grabación; no es evidencia de entrevista temática. Confirmar el audio y no contarlo como participante.\n3. Duración no recuperada para algunos MP4/OGG. Las duraciones mostradas no representan la duración total del corpus.\n4. La transcripción de Audio7 carece de cabecera clara y muestra posibles errores ASR. La atribución de voces de varios archivos es provisional.\n5. No se encontró aquí un padrón fiable de entrevistas que permita reportar un N definitivo de personas únicas, edad, género, hogar u otros datos sociodemográficos.\n6. No hay evidencia de entrevista rural/agricultor en este lote; el guion rural es planificación para otra salida.\n7. Los permisos deben cotejarse uno a uno; la autorización compartida prohíbe usar nombres en resultados. Por esto no se publican nombres, aunque aparezcan en los .txt.\n\n## Decisión QA\n**Aprobado como análisis descriptivo exploratorio y producto de trabajo; no aprobado como set de datos validado ni estadística representativa.** Cualquier cifra del deck queda rotulada como conteo del corpus o dato de integridad, no como prevalencia de Usme. La escala afectiva automatizada se excluye de conclusiones.\n'''
(OUT/'Reporte_QA_Final.md').write_text(qa,encoding='utf-8')

# Build anonymous visual carousel.
slide_data=[]
def add(kicker,title,subtitle,body,quote=None,chart=None): slide_data.append(dict(kicker=kicker,title=title,subtitle=subtitle,body=body,quote=quote,chart=chart))
add('RECOEVO · TRABAJO DE CAMPO','Lo que Usme cuenta sobre sus residuos orgánicos','Lectura exploratoria de entrevistas urbanas · UPZ Gran Yomasa · 19 sep 2026','Conversaciones, prácticas cotidianas y oportunidades para diseñar un aprovechamiento viable.')
add('FICHA TÉCNICA','El corpus, con sus límites a la vista','Inventario de archivos; no confundir audios con personas',f'<div class="stats"><b>{len(inventory)}<small>audios encontrados</small></b><b>{len(substantive)}<small>textos sustantivos &gt;250 palabras</small></b><b>{duration_str}<small>duración parcial legible</small></b><b>{len(respondent)}<small>unidades atribuibles provisionalmente</small></b></div><p>Hay hogares, comerciantes y líderes urbanos. Audio2 es un fragmento de 26 s; Audio10 parece una autorización. El número de personas únicas y la duración total siguen por confirmar.</p>')
add('FICHA TÉCNICA','Quiénes aparecen en las voces','Identidades anonimizadas por el consentimiento', 'Las transcripciones refieren a residentes/hogares, comerciantes o trabajadores de locales y líderes comunitarios. Los nombres se excluyen de los resultados. El corpus no permite todavía contar personas únicas: algunas voces pueden repetirse entre archivos. Edad, género y otros datos personales no están verificados de forma uniforme.')
add('FICHA TÉCNICA','Duración y emparejamiento','Duraciones legibles por metadatos · total parcial', '<div class="bars">'+''.join(f'<div><span>{x["id"]}</span><i style="--w:{(to_seconds(x["duracion"])/798*100 if to_seconds(x["duracion"]) else 0):.1f}%"></i><em>{x["duracion"]}</em></div>' for x in inventory)+'</div><p>Suma parcial {duration_str} ({known_duration_count} archivos con duración legible). MP4/OGG no siempre exponen duración. Revisar si Audio2–4 son segmentos de una entrevista.</p>')
add('MÉTODO','Cómo pasamos de conversación a evidencia','Análisis de marco · unidades de significado · fuente y contexto', 'Primero validar audio y texto; luego segmentar intervenciones, separar entrevistador/participante, aplicar un libro de códigos, comparar hogares y comercios y mantener citas rastreables. Una unidad puede tener varias etiquetas y varias unidades pueden pertenecer a una sola persona.')
add('MÉTODO','Una escala de caritas no mide “felicidad” automáticamente','Sentimiento y evaluación del problema son variables distintas','Las expresiones negativas sobre la basura describen una valoración del fenómeno, no necesariamente el estado emocional global de quien habla. La puntuación automática se conserva sólo como pista interna y no se presenta como hallazgo.')
add('HALLAZGO 01','La separación compite con la rutina','La práctica aparece condicionada por tiempo, hábitos y facilidad de uso',f'<p>{topic_counts["separacion_y_cultura"]} unidades de participante contienen palabras asociadas a separación/cultura (etiquetado automático, multietiqueta).</p>',quotes[2])
add('HALLAZGO 02','La basura se vuelve visible en el espacio compartido','Disposición y recolección son parte central de la experiencia',f'<p>{topic_counts["disposicion_y_recoleccion"]} unidades contienen referencias a disposición/recolección.</p>',quotes[0])
chart_labels={'separacion_y_cultura':'Separación y cultura','disposicion_y_recoleccion':'Disposición y recolección','impactos_y_salud':'Impactos y salud','generacion_y_desperdicio':'Generación y desperdicio','soluciones_y_participacion':'Soluciones y participación','confianza_y_gobernanza':'Confianza y gobernanza'}
max_topic=max(topic_counts.values()) or 1
topic_chart='<div class="bars">'+''.join(f'<div><span>{chart_labels[k]}</span><i style="--w:{v/max_topic*100:.1f}%"></i><em>{v} unidades</em></div>' for k,v in topic_counts.items())+'</div><p>Conteos automáticos con etiquetas solapables; no son porcentajes de personas ni frecuencia poblacional.</p>'
