template='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RECOEVO · Voces de Gran Yomasa</title><style>
:root{--ink:#102e23;--leaf:#315d42;--lime:#c7ed8c;--paper:#f5f4eb;--muted:#5f7668;--line:#d7e0d3}*{box-sizing:border-box}body{margin:0;background:#15251d;color:var(--ink);font-family:Inter,Segoe UI,Arial,sans-serif;overflow:hidden}.deck{height:100dvh;display:flex;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;scroll-behavior:smooth;scrollbar-width:none}.deck::-webkit-scrollbar{display:none}.slide{scroll-snap-align:start;flex:0 0 100vw;width:100vw;height:100dvh;padding:4.8vh 7vw 11vh;background:radial-gradient(ellipse at 88% 18%,#e0efcf 0,transparent 34%),var(--paper);position:relative;display:flex;flex-direction:column;justify-content:center;overflow:hidden}.slide:nth-child(even){background:radial-gradient(ellipse at 4% 92%,#e1ead9 0,transparent 32%),#fbfaf5}.kicker{font-size:clamp(13px,1.2vw,19px);font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:#5a815e;margin-bottom:2vh}.slide h1{font-size:clamp(46px,7vw,110px);line-height:.96;letter-spacing:-.055em;max-width:1000px;margin:0 0 2.4vh}.slide h2{font-size:clamp(38px,5.1vw,76px);line-height:1.01;letter-spacing:-.045em;max-width:1200px;margin:0 0 2vh}.subtitle{font-size:clamp(21px,2vw,32px);color:var(--muted);margin-bottom:3vh;max-width:900px}.content{font-size:clamp(21px,2.05vw,31px);line-height:1.38;max-width:1180px}.content p{margin:.7em 0}.quote{margin-top:3vh;padding:1.5vh 2vw;border-left:5px solid #7fa64d;background:#fff9;border-radius:0 18px 18px 0;max-width:1080px;font-size:clamp(19px,1.65vw,26px);line-height:1.32}.quote footer{font-size:15px;color:var(--muted);margin-top:10px}.stats{display:flex;gap:1.4vw;flex-wrap:wrap;margin:1vh 0 2vh}.stats b{background:#173d2c;color:#eaffd9;border-radius:24px;padding:1.1rem 1.4rem;font-size:clamp(30px,3.2vw,52px);min-width:190px}.stats small{display:block;font-size:15px;font-weight:500;color:#d0e2ce;margin-top:5px}.bars{max-width:900px;display:grid;gap:10px;margin:1vh 0}.bars div{display:grid;grid-template-columns:90px 1fr 115px;align-items:center;gap:12px;font-size:17px}.bars i{height:15px;border-radius:20px;background:linear-gradient(90deg,#317047,#a7d564);width:var(--w);animation:grow 1.2s ease-out both}.bars em{font-style:normal;color:var(--muted)}@keyframes grow{from{transform:scaleX(.05);transform-origin:left}to{transform:scaleX(1);transform-origin:left}}.footer{position:absolute;bottom:3vh;left:7vw;right:7vw;display:flex;align-items:center;gap:14px;color:#476352;font-size:14px}.progress{height:5px;background:#d6dfd3;border-radius:9px;flex:1;overflow:hidden}.progress b{height:100%;display:block;background:#4d7d48;width:0;transition:width .35s}.nav{position:absolute;right:7vw;bottom:6.5vh;display:flex;gap:10px}.nav button{border:0;border-radius:99px;width:46px;height:46px;background:#173d2c;color:white;font-size:23px;cursor:pointer}.nav button:hover{background:#46804a}.count{min-width:58px}.covermark{position:absolute;right:8vw;bottom:20vh;width:22vw;max-width:300px;aspect-ratio:1;border:1px solid #9db495;border-radius:50%;display:grid;place-items:center;color:#447251;font-size:clamp(15px,2vw,26px);font-weight:800;transform:rotate(-12deg)}.covermark:before,.covermark:after{content:"";position:absolute;border:1px solid #b1c6a7;border-radius:50%;inset:12%;transform:rotate(36deg)}.covermark:after{inset:25%;transform:rotate(-40deg)}@media(max-width:700px){.slide{padding:6vh 7vw 13vh}.covermark{right:7vw;bottom:14vh;width:30vw;opacity:.35}.stats b{min-width:130px}.bars div{grid-template-columns:64px 1fr 90px}.footer{font-size:11px}}
</style></head><body><main class="deck" id="deck"></main><script>const slides=SLIDES;const deck=document.getElementById('deck');slides.forEach((s,i)=>{let sec=document.createElement('section');sec.className='slide';sec.innerHTML=`<div class="kicker">${s.kicker}</div>${i===0||i===slides.length-1?`<h1>${s.title}</h1>`:`<h2>${s.title}</h2>`}<div class="subtitle">${s.subtitle}</div><div class="content">${s.body}</div>${s.quote?`<blockquote class="quote">“${s.quote.texto}”<footer>— ${s.quote.archivo} · cita anonimizada; verificar transcripción/audio</footer></blockquote>`:''}${i===0?'<div class="covermark">RE<br>COEVO</div>':''}<div class="footer"><span>RECOEVO · GRAN YOMASA</span><div class="progress"><b></b></div><span class="count">${String(i+1).padStart(2,'0')} / ${slides.length}</span></div><div class="nav"><button aria-label="Anterior" data-dir="-1">‹</button><button aria-label="Siguiente" data-dir="1">›</button></div>`;deck.appendChild(sec)});function go(d){let n=Math.max(0,Math.min(slides.length-1,Math.round(deck.scrollLeft/innerWidth)+d));deck.scrollTo({left:n*innerWidth,behavior:'smooth'})}document.addEventListener('click',e=>{if(e.target.matches('[data-dir]'))go(+e.target.dataset.dir)});document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();go(1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(-1)}if(e.key==='Home')deck.scrollTo({left:0,behavior:'smooth'});if(e.key==='End')deck.scrollTo({left:(slides.length-1)*innerWidth,behavior:'smooth'})});const obs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){let b=e.target.querySelector('.progress b');b.style.width=((Array.from(deck.children).indexOf(e.target)+1)/slides.length*100)+'%'}}),{root:deck,threshold:.6});document.querySelectorAll('.slide').forEach(s=>obs.observe(s));</script></body></html>'''.replace('SLIDES',slide_json)
